#!/usr/bin/env bash
# Documentation : la garde contre la production.
# Prérequis : apply-fix-garde-prod.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-garde-prod.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null | grep -qF "### Une garde contre la production"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export function assertLocalTarget" "prisma/db-target.mjs" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-garde-prod.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/mise-en-route.mdx" "apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" "apps/web/content/docs/dev/formulaires/choisir-son-modele.mdx" "apps/web/content/docs/dev/infrastructure/mettre-en-production.mdx")
EXPECT=("e14f0ffef74c:apps/web/content/docs/dev/demarrer/mise-en-route.mdx" "ed683be0b60e:apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" "69d182fa7fd3:apps/web/content/docs/dev/formulaires/choisir-son-modele.mdx" "a8fe21c0c285:apps/web/content/docs/dev/infrastructure/mettre-en-production.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "### Une garde contre la production" "apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
sub('apps/web/content/docs/dev/demarrer/mise-en-route.mdx', '',
    '')
sub('apps/web/content/docs/dev/demarrer/mise-en-route.mdx', 'YGBganNvbgovLyBwYWNrYWdlLmpzb24gKGV4dHJhaXQpCiJkYjpzZWVkOmRldiI6ICJub2RlIC0tZW52LWZpbGU9LmVudiBwcmlzbWEvc2VlZC5zYW5kYm94Lm1qcyIsCmBgYAoK',
