sub('apps/web/content/docs/dev/formulaires/choisir-son-modele.mdx', 'YGBgdHN4Ci8vIGFwcHMvd2ViL3NyYy9mZWF0dXJlcy9hZG1pbi9kaXNjaXBsaW5lcy9mb3Jtcy9EaXNjaXBsaW5lRm9ybS50c3ggKGV4dHJhaXQpCiAgICAgIDxkaXYgY2xhc3NOYW1lPSJmbGV4IGp1c3RpZnktZW5kIGdhcC0yIj4KICAgICAgICA8YnV0dG9uCiAgICAgICAgICB0eXBlPSJidXR0b24iCg==',
    'YGBgdHN4Ci8vIGFwcHMvd2ViL3NyYy9mZWF0dXJlcy9hZG1pbi9kaXNjaXBsaW5lcy9mb3Jtcy9EaXNjaXBsaW5lRm9ybS50c3ggKGV4dHJhaXQpCiAgICAgIDxkaXYgY2xhc3NOYW1lPSJmbGV4IGp1c3RpZnktZW5kIGdhcC0yIiBkYXRhLXRvdXI9ImRpc2NpcGxpbmVzLmZvcm0uc3VibWl0Ij4KICAgICAgICA8YnV0dG9uCiAgICAgICAgICB0eXBlPSJidXR0b24iCg==')
